const tabId = 1962625075;

const info = await browserjs(tabId, () => {
  const h2 = Array.from(document.querySelectorAll('h2')).find(h => h.textContent.includes('2. Sign up here'));
  if (!h2) return "h2 not found";
  let cur = h2;
  const tree = [];
  while (cur && cur !== document.body) {
    tree.push({
      tag: cur.tagName,
      className: cur.className,
      childrenCount: cur.children.length,
      innerHTML: cur.innerHTML.slice(0, 300)
    });
    cur = cur.parentElement;
  }
  return {
    tree,
    inputs: Array.from(document.querySelectorAll('input')).map(i => ({
      id: i.id,
      name: i.name,
      type: i.type,
      value: i.value,
      className: i.className,
      visible: i.offsetWidth > 0 && i.offsetHeight > 0
    })),
    buttons: Array.from(document.querySelectorAll('button')).map(b => ({
      id: b.id,
      text: b.textContent.trim(),
      className: b.className,
      visible: b.offsetWidth > 0 && b.offsetHeight > 0
    }))
  };
});

console.log("Inputs:", JSON.stringify(info.inputs, null, 2));
console.log("Buttons:", JSON.stringify(info.buttons, null, 2));

